    }
    try (final ConsumerLease lease = testPool.obtainConsumer(mockSession, mockContext)) {
        lease.poll();
    }
    try (final ConsumerLease lease = testPool.obtainConsumer(mockSession, mockContext)) {
        lease.poll();
