            throw new IOException("Intentional Unit Test Exception");
        }
    };
    try {
        lease.publish(flowFile, failureInputStream, messageKey, demarcatorBytes, topic);
        Assert.fail("Expected IOException");
    } catch (final IOException ioe) {
